//! Real loopback TCP: bounded slow-subscriber isolation, drain, then an explicit
//! application reset handshake. IR/RA below are EXAMPLE host control messages,
//! not negotiated engine protocol. No production account/save data is used.
use infinite_core::*;
use std::{io::{self,Read,Write},net::{TcpListener,TcpStream,Shutdown},num::{NonZeroU16,NonZeroU32},sync::mpsc,thread,time::{Duration,Instant}};
type Result<T>=std::result::Result<T,Box<dyn std::error::Error>>;
fn error(e:impl std::fmt::Debug)->io::Error{io::Error::other(format!("{e:?}"))}
fn n(v:u32)->NonZeroU32{NonZeroU32::new(v).unwrap()}
struct ClientResult {events:Vec<CombatFeedback>,resets:usize,hp:u32,duplicates:usize}
fn client(mut socket:TcpStream,mut stream:u64,gate:Option<mpsc::Receiver<()>>)->io::Result<ClientResult>{
 socket.set_read_timeout(Some(Duration::from_secs(5)))?;socket.set_write_timeout(Some(Duration::from_secs(5)))?;socket.set_nodelay(true)?;
 if let Some(gate)=gate{gate.recv_timeout(Duration::from_secs(3)).map_err(error)?;}
 let mut replica=CombatReplica::new_windowed(stream);let mut out=ClientResult{events:Vec::new(),resets:0,hp:0,duplicates:0};
 loop{let mut prefix=[0;4];match socket.read(&mut prefix[..1]){Ok(0)=>break,Ok(_)=>{},Err(e)=>return Err(e)}socket.read_exact(&mut prefix[1..])?;let length=u32::from_le_bytes(prefix)as usize;if !(28..=MAX_COMBAT_SYNC_PACKET_BYTES).contains(&length){return Err(error("length bound"));}let mut bytes=vec![0;length];socket.read_exact(&mut bytes)?;
  if bytes.starts_with(b"IR\x01\x00"){
   if bytes.len()!=28||out.resets!=0{return Err(error("reset format/count"));}let old=u64::from_le_bytes(bytes[4..12].try_into().unwrap());let new=u64::from_le_bytes(bytes[12..20].try_into().unwrap());let boundary=u64::from_le_bytes(bytes[20..28].try_into().unwrap());assert_eq!(old,stream);assert_ne!(new,old);assert_eq!(out.events.iter().map(|e|e.tick.0).collect::<Vec<_>>(),(1..=boundary).collect::<Vec<_>>());
   stream=new;replica=CombatReplica::new_windowed(stream);out.resets+=1;let mut ack=[0;20];ack[..4].copy_from_slice(b"RA\x01\x00");ack[4..12].copy_from_slice(&stream.to_le_bytes());ack[12..].copy_from_slice(&boundary.to_le_bytes());socket.write_all(&ack[..3])?;socket.write_all(&ack[3..])?;continue;
  }
  let applied=replica.apply(&bytes).map_err(error)?;out.duplicates+=usize::from(applied.duplicate);
  for event in replica.drain_feedback(){assert_eq!((event.attacker.index,event.target.index),(0,1));let t=event.tick.0;if t%2==1{assert_eq!(event.kind,CombatFeedbackKind::WindupStarted{started_at:Tick(t),hit_at:Tick(t+1)});}else{assert_eq!(event.kind,CombatFeedbackKind::Hit{damage:1,remaining:1000-(t/2)as u32});}out.events.push(event);}
  let tick=applied.tick.0;out.hp=replica.states().iter().find(|s|s.entity.index==1).and_then(|s|s.health).unwrap().current;assert_eq!(out.hp,1000-(tick/2)as u32);let attacker=replica.states().iter().find(|s|s.entity.index==0).unwrap();assert_eq!(attacker.windup.is_some(),tick%2==1);let ack=applied.acknowledgement();socket.write_all(&ack[..3])?;socket.write_all(&ack[3..])?;
 }Ok(out)
}
fn main()->Result<()>{
 let listener=TcpListener::bind("127.0.0.1:0")?;let(mut sockets,mut clients)=(Vec::new(),Vec::new());let(tx,rx)=mpsc::channel();let mut rx=Some(rx);
 for i in 0..2{let client_socket=TcpStream::connect(listener.local_addr()?)?;let(server,_)=listener.accept()?;server.set_nonblocking(true)?;server.set_nodelay(true)?;sockets.push(server);let gate=if i==0{rx.take()}else{None};clients.push(thread::spawn(move||client(client_socket,700+i,gate)));}
 let mut w=World::default();let a=w.spawn(GridPosition::default()).map_err(error)?;let b=w.spawn(GridPosition{x:16,y:0}).map_err(error)?;for e in [a,b]{w.configure_health(e,1000,n(1000)).map_err(error)?;}w.start_attack(a,b,AttackProfile{range:32,damage:n(1),cooldown_ticks:NonZeroU16::new(1).unwrap(),windup_ticks:1}).map_err(error)?;
 let mut net=CombatConnections::with_window(700,NetworkConfig{connections:2,quantum_bytes:23,retry_ms:50,ack_timeout_ms:2000,combat:CombatSyncConfig{pending_events:4,events_per_packet:1},..NetworkConfig::default()},2).map_err(error)?;let ids=[net.connect().map_err(error)?,net.connect().map_err(error)?];let view=ViewRect{min:GridPosition{x:-64,y:-64},max:GridPosition{x:64,y:64}};let mut targets=ids.map(|connection|ObservationTarget{connection,view}).to_vec();let mut q=ObservationQueue::new(2).map_err(error)?;let mut recovery:Option<ObservationRecovery>=None;let mut frame=CombatFrame::new(n(64));let mut expected=Vec::new();let mut oracle=CombatReplica::new(999);let mut reference=CombatSyncSender::new_shielded(999,CombatSyncConfig::default()).map_err(error)?;
 let mut acks=[[0;20];2];let mut filled=[0usize;2];let mut failures=Vec::new();let mut notices=Vec::new();let(mut ticks,mut next_tick,mut boundary,mut resumed_first)=(0u64,0u64,0u64,0u64);let(mut sent,mut retries,mut stale_acks)=(0usize,0usize,0usize);let mut released=false;let mut control:Option<(Vec<u8>,usize,u64)>=None;let mut waiting_reset=None;let start=Instant::now();
 loop{let now=start.elapsed().as_millis()as u64;if now>5000{return Err(error("bounded example deadline").into());}
  if ticks<40&&now>=next_tick{w.advance_tick().map_err(error)?;let h=w.health(b).map_err(error)?;let mut ev=[CombatEvent{attacker:a,target:b,kind:CombatEventKind::Ended(CombatEndReason::TargetGone)}];let mut changes=[HealthChange{entity:b,before:h,after:h}];let r=w.resolve_combat(&mut ev,&mut changes).map_err(error)?;assert_eq!(r.events_written,1);frame.capture(&w,&ev[..1]).map_err(error)?;reference.observe(&frame,view).map_err(error)?;let packet=reference.prepare().map_err(error)?.unwrap();let applied=oracle.apply(packet).map_err(error)?;expected.extend(oracle.drain_feedback());reference.acknowledge_packet(&applied.acknowledgement()).map_err(error)?;
   match q.enqueue(&net,&frame,&targets){Ok(())=>{},Err(ObservationError::Full)=>{assert!(recovery.is_none()&&boundary==0,"one bounded recovery slot");let isolated=q.extract(ids[0]).ok_or_else(||error("expected slow subscriber"))?;boundary=isolated.last_reserved_serial();recovery=Some(isolated);targets.retain(|t|t.connection!=ids[0]);q.enqueue(&net,&frame,&targets).map_err(error)?;},Err(e)=>return Err(error(e).into())}ticks+=1;next_tick=now+10;
   if ticks==12{assert!(boundary>0,"slow subscriber isolated before read release");tx.send(()).map_err(error)?;released=true;}
  }
  for i in 0..2{loop{match sockets[i].read(&mut acks[i][filled[i]..]){Ok(0)=>return Err(error("early EOF").into()),Ok(count)=>{filled[i]+=count;if filled[i]==20{let ack=&acks[i];let stream=u64::from_le_bytes(ack[4..12].try_into().unwrap());if ack.starts_with(b"RA\x01\x00"){assert_eq!(i,0);assert_eq!(waiting_reset.take(),Some(stream));assert_eq!(u64::from_le_bytes(ack[12..].try_into().unwrap()),boundary);net.resume(ids[0]).map_err(error)?;targets.push(ObservationTarget{connection:ids[0],view});resumed_first=ticks+1;}else if stream==net.status(ids[i]).map_err(error)?.stream{net.acknowledge(ids[i],ack).map_err(error)?;}else{assert_eq!((i,stream),(0,700));stale_acks+=1;}filled[i]=0;}},Err(e)if e.kind()==io::ErrorKind::WouldBlock=>break,Err(e)if e.kind()==io::ErrorKind::Interrupted=>continue,Err(e)=>return Err(e.into())}}}
  let mut budget=NetworkBudget{work:8,bytes:97};if let Some(recovery)=&mut recovery{match recovery.replay(&mut net,&mut budget){Ok(_)=>{},Err(ObservationError::Network(NetworkError::Sync(CombatSyncError::EventBackpressure)))=>{},Err(e)=>return Err(error(e).into())}}
  q.poll(&mut net,&mut budget,&mut failures).map_err(error)?;assert!(failures.iter().all(|f|f.connection==ids[0]&&f.error==NetworkError::Sync(CombatSyncError::EventBackpressure)));
  if recovery.as_ref().is_some_and(|r|r.is_empty())&&{let s=net.status(ids[0]).map_err(error)?;s.pending_bytes==0&&s.queued_events==0}{net.detach(ids[0]).map_err(error)?;let restart=recovery.take().unwrap().try_restart(&mut net).map_err(|(_,e)|error(e))?;let mut bytes=Vec::new();bytes.extend_from_slice(&28u32.to_le_bytes());bytes.extend_from_slice(b"IR\x01\x00");bytes.extend_from_slice(&restart.old_stream.to_le_bytes());bytes.extend_from_slice(&restart.new_stream.to_le_bytes());bytes.extend_from_slice(&restart.last_reserved_serial.to_le_bytes());control=Some((bytes,0,restart.new_stream));}
  // Control owns the detached peer until its complete framed reset is written;
  // it consumes the SAME host byte/work budget as normal transmission.
  if let Some((bytes,offset,stream))=&mut control{if budget.work>0&&budget.bytes>0{budget.work-=1;let part=&bytes[*offset..(*offset+23.min(budget.bytes)).min(bytes.len())];match sockets[0].write(part){Ok(n)=>{*offset+=n;budget.bytes-=n;sent+=n;},Err(e)if matches!(e.kind(),io::ErrorKind::WouldBlock|io::ErrorKind::Interrupted)=>{},Err(e)=>return Err(e.into())}if *offset==bytes.len(){waiting_reset=Some(*stream);control=None;}}}
  let r=net.poll(now,&mut budget,&mut notices,|id,p|match sockets[id.index as usize].write(p){Ok(n)=>WriteProgress::Written(n),Err(e)if matches!(e.kind(),io::ErrorKind::WouldBlock|io::ErrorKind::Interrupted)=>WriteProgress::WouldBlock,Err(_)=>WriteProgress::Disconnected}).map_err(error)?;assert!(notices.is_empty());sent+=r.bytes;retries+=r.retries;
  if ticks==40&&q.pending()==0&&recovery.is_none()&&control.is_none()&&waiting_reset.is_none()&&resumed_first>0&&ids.iter().all(|&id|{let s=net.status(id).unwrap();s.pending_bytes==0&&s.queued_events==0}){break;}thread::sleep(Duration::from_millis(1));
 }
 assert!(released&&resumed_first>boundary+1&&resumed_first<=40);assert_eq!(expected.len(),40);assert_eq!(w.health(b).map_err(error)?.current,980);for socket in &sockets{socket.shutdown(Shutdown::Write)?;}let mut results=Vec::new();for c in clients{results.push(c.join().map_err(|_|error("client panic"))??);}assert_eq!(results[1].events,expected);assert_eq!(results[1].resets,0);let subscribed:Vec<_>=expected.iter().copied().filter(|e|e.tick.0<=boundary||e.tick.0>=resumed_first).collect();assert_eq!(results[0].events,subscribed);assert_eq!(results[0].resets,1);assert!(results.iter().all(|r|r.hp==980));println!("healthy_events=40 slow_events={} old_through={boundary} new_from={resumed_first} unsubscribed={} final_hp=980 reset_handshakes=1 bytes={sent} retries={retries} stale_acks={stale_acks} duplicates={:?}",subscribed.len(),resumed_first-boundary-1,results.iter().map(|r|r.duplicates).collect::<Vec<_>>());Ok(())
}
